const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(BigInt);
let idx = 0;
const M = 1000000007n;

function getx(N) {
  if (N < 30n) {
    return 1n << N;
  }
  if (N % 2n === 0n) {
    const Y = getx(N >> 1n);
    return (Y * Y) % M;
  }
  return (getx(N - 1n) * 2n) % M;
}

function main() {
  if (input.length < 2) {
    console.log('0');
    return;
  }
  let N = input[idx++];
  const K = input[idx++];

  if (N === 0n) {
    console.log('0');
    return;
  }

  N = (2n * N - 1n) % M;
  const z = getx(K);
  const ans = (z * N + 1n) % M;
  console.log(ans.toString());
}

