package main

import (
	"bufio"
	"fmt"
	"os"
)

var (
	bufin  = bufio.NewReader(os.Stdin)
	bufout = bufio.NewWriter(os.Stdout)
)

func printf(f string, a ...interface{}) { fmt.Fprintf(bufout, f, a...) }
func scanf(f string, a ...interface{})  { fmt.Fscanf(bufin, f, a...) }

/*
f(x) = 2*x - .5
4*x - 1.5
2^(n+1) x - (2^n - 1)
*/

const M = 1000000007

func main() {
	defer bufout.Flush()
	var N, K uint64
	scanf("%d%d", &N, &K)
	if N == 0 {
		printf("0\n")
		return
	}
	N = (2*N - 1) % M
	z := getx(K)
	printf("%d\n", (int64(z)*int64(N)+1)%M)
}

func getx(N uint64) int {
	if N < 30 {
		return 1 << N
	}
	if N%2 == 0 {
		Y := getx(N >> 1)
		return int(int64(Y) * int64(Y) % M)
	}
	return getx(N-1) * 2 % M
}
